settings._cssCustom:
.checkout-page-2__customer-details {

		--customer-details--primary: var(--black);
  	--focus-color: var(--customer-details--primary);


  	/* Change accent color of checkbox and radio */
  	input[type="checkbox"],
    input[type="radio"] {
      accent-color: var(--customer-details--primary);
    }

  	/* Set container of billing and shiiping fiedls to display flex */
  	.col2-set {
    display: flex;
    flex-direction: column;
    gap: var(--content-gap);
}

  .col-2 {
    display: flex;
    flex-direction: column;
    gap: var(--content-gap);
}

  	/* Sets margin-bottom of h3 element */
		.woocommerce-shipping-fields > h3, .woocommerce-billing-fields > h3 {
      margin-bottom: var(--space-m);
    }

  #ship-to-different-address label {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }

  .woocommerce-shipping-fields h3 span {
    font-size: var(--text-l) !important;
    order: -1;
    color: var(--customer-details--primary);
    font-weight: 700;

  }





}

.checkout-page-2__order-review {  	
  	--order-review--primary: var(--black);
  	--order-review--border: var(--neutral-light);
  	--focus-color: var(--order-review--primary);

  	/* Removes border around checkout element */
  	#order_review {
    	border: 0;
      display: flex;
      flex-direction: column;
      gap: var(--space-m);
  	}  	

  	#payment .payment_methods input[type="checkbox"],
  	#payment .payment_methods input[type="radio"]  {
      	accent-color: var(--order-review--primary);

  	}  	

		#order_review_heading {
				display: none;
		}


		/* Shop table styling */
		.shop_table {
     		text-align: left;
      	border-spacing: 0;
      	border: 0;
  	}		

  	/* Style shop table table cell */
		.shop_table thead th {
        text-align: left;
        background-color: var(--order-review--border);
        width: 50%;
    }

    /* Align subtotal column to the right */
  .shop_table .cart-subtotal td, .shop_table .order-total td, .shop_table .cart_item .product-total, .shop_table .product-total {
    	text-align: end;
  }

    /* Right align the shipping methods*/
  ul.woocommerce-shipping-methods li {
    display: flex;
    flex-direction: row;
    justify-content: end;
	}
  	/* Sets padding on td and th elements */
		.shop_table td,
  	.shop_table th {
    		padding: var(--space-xs);
  	}

  	/* Sets the border-bottom of the shop table to 0 */
  	.shop_table tfoot {
      	border-bottom: 0;
  	}

  	/* Sets table rows background color */
    .shop_table tbody tr {
      	background-color: var(--white);
    }

  	/* Sets left and bottom border of product name */
  	#order_review .product-name {
				border-left: 1px solid var(--order-review--border);
		}

  	/* Sets left and bottom border of product total */
    #order_review .product-total {
				border-right: 1px solid var(--order-review--border);
				font-weight: bold;
		}

  	/* Sets bottom border of last of type cart item */
  	#order_review .cart_item:last-of-type td {
      	border-bottom: 1px solid var(--order-review--border);
  	}

  	/* Sets bottom border of cart subtotal */
		.cart-subtotal th,
  	.cart-subtotal td {
      	border-bottom: 1px solid var(--order-review--border) !important;
  	} 

  	/* Styles Subtotal font weight */
    .shop_table tfoot th {
      	font-weight: normal;
    }

  	/* Styles Subtotal price font weight */
    .shop_table tfoot td {
      	font-weight: bold;            
    }			

  	/* Styles order total font size and weight */
    .order-total th {
      	font-size: var(--text-l);
      	font-weight: 500;
    }

  	/* Styles order total price font size */
    .order-total .amount {
      	font-size: var(--text-l);
    }

  	/* Styles payment content wrapper */
    #payment ul {
      list-style-type: none;
      padding-inline: 0;


    }

  	/* Styles payment label */
    #payment label {
        display: inline;
        color: var(--order-review--primary);
        font-weight: bold;
      	font-size: var(--text-m) !important;
    }		

  	/* Styles payment Paragraph */  
    #payment .payment_box p {
     margin: var(--space-xs) 0;
      padding: var(--space-xs);
      font-size: var(--text-s);
    }

  /* Styles woo privacy policy margin */  
    #payment .woocommerce-privacy-policy-text p {
      	margin: var(--space-xs) 0;
      	font-size: var(--text-s);
    }

  	/* Styles input checkbox */  
    #payment .input-checkbox {
      	accent-color: var(--order-review--primary);
      	margin-right: 0.6rem;
    }

  	/* Styles input checkbox span element */  
    #payment .input-checkbox span {
      	margin-left: 1rem;
    }

  	/* Styles privacy policy link */  
    #payment .woocommerce-privacy-policy-link {
        color: var(--order-review--primary);
        font-weight: 600;
    }  

  	/* Styles payment button */  
    #payment button {
      padding: var(--space-xs) var(--space-xs); 
      background-color: var(--order-review--primary);
      color: var(--white);
      font-weight: normal;
      font-size: var(--text-m);
      line-height: 1.5rem;
      text-align: center;
      width: 100%;
    }

}
